function lunchSpotlight(){return `<section class="lunch-spotlight" id="plan-lunch"><div class="planner-intro"><div><span class="eyebrow">THE OFFICE LUNCH, REIMAGINED</span><h2>Less organising.<br><em>More lunching.</em></h2></div><div><p>A working lunch worth taking a break for. Build your mix, add the details and bring a clear brief to the Feast team.</p><a class="quietlink" href="/how-it-works" data-route>How it works ↗</a></div></div><div class="planner-layout"><div class="quick-menu">${products.map((p,i)=>`<article class="quick-card"><div class="quick-photo">${art(p.id)}<span>0${i+1} / FRESHLY INSPIRED</span></div><div class="quick-body"><span class="tinytitle">${p.unit==='box'?'THE FRESH PICK':'THE LUNCH FAVOURITE'}</span><h3>${p.label}</h3><div class="quick-price">${money(p.price)}<small> / ${p.unit}</small></div><div class="quick-qty"><button data-quick="${p.id}" data-delta="-1" aria-label="Remove one ${p.label}">−</button><output id="quick-${p.id}" aria-label="${p.label} quantity">${draft.qty[p.id]}</output><button data-quick="${p.id}" data-delta="1" aria-label="Add one ${p.label}">+</button></div></div></article>`).join('')}</div><aside class="planner-ticket"><span class="tinytitle">YOUR LUNCH, COMING TOGETHER</span><h3>A very good<br><em>lunch break.</em></h3><div id="quick-lines"></div><div class="ticket-total"><span>Menu subtotal</span><strong id="quick-total"></strong></div><span class="ticket-count" id="quick-count"></span><a class="btn" href="/lunch" data-route>Build my lunch request <span>↗</span></a><p>Final pricing, availability and delivery confirmed by the team.</p><div class="ticket-bottom">FEAST CATERING <b>✳</b> NEWCASTLE & THE HUNTER</div></aside></div><div class="planner-steps"><div><b>01</b><span><strong>Choose your mix</strong>Sandwiches, wraps & salads.</span></div><div><b>02</b><span><strong>Set the scene</strong>Date, location & dietary notes.</span></div><div><b>03</b><span><strong>Bring it all together</strong>Review a brief for the team.</span></div></div></section>`}
function syncPlanner(){let t=totals();document.querySelectorAll('.request-count').forEach(e=>{e.textContent=t.count;e.setAttribute('aria-label',t.count+' items in lunch request')});products.forEach(p=>{let e=document.getElementById('quick-'+p.id);if(e)e.textContent=draft.qty[p.id]});let lines=document.querySelector('#quick-lines');if(lines){lines.innerHTML=t.count?products.filter(p=>draft.qty[p.id]>0).map(p=>`<div class="ticket-line"><span>${draft.qty[p.id]} × ${p.label}</span><b>${money(draft.qty[p.id]*p.price)}</b></div>`).join(''):'<p class="ticket-empty">Something delicious starts here.<br>Tap + to add your favourites.</p>';document.querySelector('#quick-total').textContent=money(t.sum);document.querySelector('#quick-count').textContent=t.count+' items selected'}}
function howPage(){return `<div class="wrap how-request"><div class="pagehead"><span class="eyebrow">FROM YOUR FIRST PICK TO THE FINAL DETAILS</span><h1>Good food.<br><em>Simple planning.</em></h1><p>Your next team lunch, in three easy steps.</p></div><div class="how-request-grid">${[['01','Build your mix.','Choose sandwiches, wraps and salad boxes. Adjust quantities and see the menu subtotal update as you go.'],['02','Tell us the details.','Add your requested date and time, headcount, delivery address and contact details. Flag any dietary questions for a conversation.'],['03','Review your brief.','Check your choices, then prepare a summary to share with the catering team. The team confirms availability, delivery, dietary suitability and final pricing.']].map(([n,h,p])=>`<article><b>${n}</b><h2>${h}</h2><p>${p}</p></article>`).join('')}</div><a class="btn" href="/lunch" data-route>Start planning lunch ↗</a><a class="quietlink" href="/menu" data-route>Explore all catering menus ↗</a></div>`}
function readyBrief(){return `<div class="ready-brief"><p>Your brief is ready to copy into an email to <strong>tracy@feastcateringnewcastle.com.au</strong>.</p><button type="button" class="btn" id="copy-lunch-brief">Copy lunch brief ↗</button><p id="brief-status" role="status"></p></div>`}
document.addEventListener('click',e=>{let b=e.target.closest('[data-quick]');if(b){let id=b.dataset.quick;draft.qty[id]=Math.max(0,Math.min(200,Number(draft.qty[id]||0)+Number(b.dataset.delta)));delete qtyErrors[id];syncPlanner();announce(`${totals().count} items. Menu subtotal ${money(totals().sum)}.`)}if(e.target.closest('#copy-lunch-brief')){let r=requests.find(r=>r.id===result?.id)||draft;let text='Feast Catering lunch request\n\n'+products.filter(p=>r.qty[p.id]).map(p=>r.qty[p.id]+' × '+p.label+' — '+money(r.qty[p.id]*p.price)).join('\n')+'\nMenu subtotal: '+money(totals(r.qty).sum)+'\n\n'+['date','time','headcount','company','name','email','phone','street','suburb','postcode','note'].filter(k=>r[k]).map(k=>k+': '+r[k]).join('\n')+'\nDietary discussion: '+(r.categories.join(', ')||'None noted')+'\n\nPlease confirm availability, delivery, dietary suitability and final pricing.';navigator.clipboard.writeText(text).then(()=>document.querySelector('#brief-status').textContent='Copied. Paste your brief into your email to the team.').catch(()=>{let out=document.createElement('textarea');out.value=text;out.rows=12;out.setAttribute('aria-label','Lunch brief to copy');document.querySelector('.ready-brief').append(out);out.select();document.querySelector('#brief-status').textContent='Select and copy your brief below.'})}});
